import json, re, sys
from docx import Document

TEMPLATE_PATH = '/root/offer_letter_template.docx'
DATA_PATH = '/root/employee_data.json'
OUTPUT_PATH = '/root/offer_letter_filled.docx'

# Load data
with open(DATA_PATH, 'r') as f:
    data = json.load(f)

# Helper to replace placeholders in a paragraph robustly
def replace_in_paragraph(paragraph, data_dict):
    full_text = paragraph.text
    # Find all placeholders {{KEY}}
    matches = re.findall(r'\{\{([A-Z_]+)\}\}', full_text)
    if not matches:
        return
    new_text = full_text
    for key in matches:
        placeholder = f'{{{{{key}}}}}'
        if key in data_dict:
            new_text = new_text.replace(placeholder, str(data_dict[key]))
        else:
            new_text = new_text.replace(placeholder, '')
    if new_text != full_text:
        # Rebuild runs: put new_text into first run, clear others
        runs = paragraph.runs
        if runs:
            runs[0].text = new_text
            for r in runs[1:]:
                r.text = ''
        else:
            # No runs (unlikely), just add a run
            paragraph.add_run(new_text)

# Helper to process conditional relocation block in a paragraph
def process_conditional(paragraph, keep_block):
    text = paragraph.text
    if '{{IF_RELOCATION}}' in text and '{{END_IF_RELOCATION}}' in text:
        # Extract inner content
        pattern = r'\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}'
        inner = re.search(pattern, text, re.DOTALL)
        if inner:
            new_text = inner.group(1) if keep_block else ''
            # Rebuild runs with new_text
            runs = paragraph.runs
            if runs:
                runs[0].text = new_text
                for r in runs[1:]:
                    r.text = ''
            else:
                paragraph.add_run(new_text)

# Load document
doc = Document(TEMPLATE_PATH)

# Determine if relocation block should be kept
relocation_flag = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

# Process body paragraphs
for para in doc.paragraphs:
    process_conditional(para, relocation_flag)
    replace_in_paragraph(para, data)

# Process tables (including nested)
def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                process_conditional(para, relocation_flag)
                replace_in_paragraph(para, data)
            for nested in cell.tables:
                process_table(nested)

for table in doc.tables:
